#include <iostream>
#include <string>
#include <unordered_map>
using namespace std;

class Solution
{
public:
    string minWindow(string s, string t)
    {

        unordered_map<char, int> tmap;
        for (int i = 0; i < t.size(); i++)
        {
            tmap[t[i]]++;
        }

        int r = -1, l = 0;
        int minLength = 1000000;
        string minString = "";
        while (r < int(s.size()))
        {
            while (!isValid(tmap) && r < int(s.size()))
            {
                r++;
                if (tmap.find(s[r]) != tmap.end())
                {
                    tmap[s[r]]--;
                }
            }

            if (r == s.size())
            { // index out of range
                return minString;
            }

            if (minLength > (r - l + 1))
            {
                minLength = (r - l + 1);
                minString = s.substr(l, r - l + 1);
            }

            while (l <= r && isValid(tmap))
            {
                if (minLength > (r - l + 1))
                {
                    minLength = (r - l + 1);
                    minString = s.substr(l, r - l + 1);
                }

                if (tmap.find(s[l]) != tmap.end())
                {
                    tmap[s[l]]++;
                }
                l++;
            }
        }
        cout << "minLength: " << minLength << endl;

        return minString;
    }

    bool isValid(unordered_map<char, int> map)
    {
        for (auto &it : map)
        {
            if (it.second > 0)
            {
                return false;
            }
        }
        return true;
    }
};

int main()
{
    Solution obj;
    string s = "";
    string t = "aAbBcCdDeEfFgGhHiIjJkKlLmMnNoOpPqQrRsStTuUvVwWxXyYzZ";
    cout << obj.minWindow(s, t) << endl;
    return 0;
}
